using System.Text.Json;

namespace BdoComboSetup.Tests;

/// <summary>
/// Paths of the synthetic asset pack fixtures (fake images, generated by tests/assetpack_support.py) and their
/// expected values. The Python builder wrote them; these tests read them.
/// </summary>
internal static class AssetPackFixtures
{
    public static string Root => Path.Combine(AppContext.BaseDirectory, "Fixtures", "assetpack");

    /// <summary>The complete pack of the synthetic inputs.</summary>
    public static string Synthetic => Path.Combine(Root, "synthetic.bdoa");

    /// <summary>The four parts of the same synthetic set (assets.part01.bdoa .. assets.part04.bdoa).</summary>
    public static string Parts => Path.Combine(Root, "parts");

    /// <summary>A part of another set (a different set id), for the wrong-set tests.</summary>
    public static string OtherSet => Path.Combine(Root, "other-set");

    /// <summary>The expected entries (key, compression, original length, SHA-256 in hex).</summary>
    public static JsonDocument ExpectedValues() =>
        JsonDocument.Parse(File.ReadAllText(Path.Combine(Root, "synthetic.expected.json")));

    /// <summary>A fresh copy of the parts folder in <paramref name="target"/> (created; the caller owns it).</summary>
    public static string CopyParts(string target)
    {
        Directory.CreateDirectory(target);
        foreach (var file in Directory.GetFiles(Parts))
        {
            File.Copy(file, Path.Combine(target, Path.GetFileName(file)), overwrite: true);
        }

        return target;
    }
}
